insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('que-tecnica-de-estudio-permite-recordar-mejor-lo-aprendido-despu','educacion',array['salud']::text[],'¿Qué técnica de estudio permite recordar mejor lo aprendido después de una semana?','Compara técnicas como releer, resumir, hacerte preguntas o explicar en voz alta, y mide cuál te deja recordar más una semana después de estudiar un mismo tipo de contenido.','Investigación','3 a 4 semanas',24,array['Memoria','Técnicas de estudio']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social diseno de experimentos. autoevaluacion. analisis sencillo de datos. redaccion de conclusiones. hoja de calculo. un cronometro. preguntas de prueba que tu mismo prepares.',$a1sld${"id": "que-tecnica-de-estudio-permite-recordar-mejor-lo-aprendido-despu", "area": "educacion", "areas2": ["salud"], "titulo": "¿Qué técnica de estudio permite recordar mejor lo aprendido después de una semana?", "resumen": "Compara técnicas como releer, resumir, hacerte preguntas o explicar en voz alta, y mide cuál te deja recordar más una semana después de estudiar un mismo tipo de contenido.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Memoria", "Técnicas de estudio"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Mucha gente estudia releyendo o subrayando porque se siente cómodo, pero eso no siempre se traduce en recordar días después. Las técnicas se comparan casi siempre al día siguiente, cuando todo está fresco.", "Medir qué queda a la semana permite elegir con evidencia propia cómo estudiar antes de un examen."], "desarrollar": ["Elige cuatro temas de dificultad parecida y estudia cada uno con una técnica distinta, por ejemplo releer, resumir, autopreguntas y explicar en voz alta, durante el mismo tiempo.", "Una semana después, responde una prueba corta de cada tema, compara puntajes y anota qué técnica fue más cómoda y cuál rindió más. Repite con otros temas para confirmar el patrón."], "ampliaciones": [{"titulo": "Con compañeros", "aporta": "repite el experimento con tres personas y compara resultados."}, {"titulo": "Tiempo de recuperación", "aporta": "mide también a las dos semanas para ver qué se olvida más."}, {"titulo": "Combinar técnicas", "aporta": "prueba si combinar dos técnicas mejora el recuerdo."}], "objetivos": ["Comparar técnicas de estudio.", "Medir el recuerdo diferido.", "Elegir una técnica con evidencia propia.", "Documentar el experimento."], "habilidades": ["Diseño de experimentos.", "Autoevaluación.", "Análisis sencillo de datos.", "Redacción de conclusiones."], "herramientas": ["Hoja de cálculo.", "Un cronómetro.", "Preguntas de prueba que tú mismo prepares."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Mantén igual el tiempo de estudio y la dificultad de los temas para que la comparación sea justa."], "otroSector": "El mismo diseño sirve para comparar técnicas de capacitación en una empresa o de aprendizaje de un idioma."}$a1sld$::jsonb,8),
('es-mas-efectivo-estudiar-en-sesiones-cortas-o-concentrarse-duran','educacion',array['salud']::text[],'¿Es más efectivo estudiar en sesiones cortas o concentrarse durante varias horas? El papel de los descansos','Compara estudiar en bloques cortos con descansos frente a maratones largas, y mide cuánto rindes, cuánto recuerdas y cómo te sientes con cada formato y con distintos tipos de descanso.','Investigación','3 semanas',22,array['Sesiones de estudio','Descansos']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social registro de datos. comparacion. autoobservacion. planificacion. hoja de calculo. un temporizador. un cuaderno de registro.',$a2sld${"id": "es-mas-efectivo-estudiar-en-sesiones-cortas-o-concentrarse-duran", "area": "educacion", "areas2": ["salud"], "titulo": "¿Es más efectivo estudiar en sesiones cortas o concentrarse durante varias horas? El papel de los descansos", "resumen": "Compara estudiar en bloques cortos con descansos frente a maratones largas, y mide cuánto rindes, cuánto recuerdas y cómo te sientes con cada formato y con distintos tipos de descanso.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Sesiones de estudio", "Descansos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Algunos juran por las maratones de varias horas y otros por bloques cortos con pausas. Casi nunca se mide con orden qué funciona para cada quien, ni se compara qué pasa con descansos de distinta duración o tipo.", "Tener datos propios ayuda a organizar los días de estudio sin copiar rutinas ajenas."], "desarrollar": ["Define tres formatos, por ejemplo bloques de 25 minutos con pausas, bloques de 50 y una sesión continua de dos horas, y estudia temas parecidos con cada uno durante tres semanas.", "Registra en una hoja cuánto avanzaste, tu nivel de concentración, cuántas veces te distrajiste y cuánto recuerdas a los dos días. Compara los formatos y también qué hacías en los descansos."], "ampliaciones": [{"titulo": "Tipo de descanso", "aporta": "compara descansar mirando el celular, caminando o sin hacer nada."}, {"titulo": "Hora del día", "aporta": "analiza si el resultado cambia según la hora de estudio."}, {"titulo": "Rutina recomendada", "aporta": "diseña una rutina propia con los resultados."}], "objetivos": ["Comparar formatos de sesión.", "Registrar rendimiento y concentración.", "Analizar el efecto de los descansos.", "Proponer una rutina."], "habilidades": ["Registro de datos.", "Comparación.", "Autoobservación.", "Planificación."], "herramientas": ["Hoja de cálculo.", "Un temporizador.", "Un cuaderno de registro."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Este proyecto no da consejos de salud: si sientes cansancio extremo o dolores al estudiar, consulta a un profesional.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "El mismo análisis sirve para organizar turnos de trabajo en oficina, estudio o programación."}$a2sld$::jsonb,9),
('el-impacto-de-la-practica-espaciada-en-el-aprendizaje-y-como-arm','educacion',array['tecnologia']::text[],'El impacto de la práctica espaciada en el aprendizaje y cómo armar un sistema personal de repaso','Mide cuánto cambia el recuerdo al repasar un tema en varios días frente a estudiarlo de una sola vez, y con lo aprendido arma un calendario personal de repasos para tus cursos.','Investigación','4 semanas',26,array['Práctica espaciada','Repaso']::text[],array['investigar','crear']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social diseno de experimentos. planificacion. autodisciplina. analisis simple de datos. hoja de calculo. un calendario. pruebas cortas propias.',$a3sld${"id": "el-impacto-de-la-practica-espaciada-en-el-aprendizaje-y-como-arm", "area": "educacion", "areas2": ["tecnologia"], "titulo": "El impacto de la práctica espaciada en el aprendizaje y cómo armar un sistema personal de repaso", "resumen": "Mide cuánto cambia el recuerdo al repasar un tema en varios días frente a estudiarlo de una sola vez, y con lo aprendido arma un calendario personal de repasos para tus cursos.", "tipo": "Investigación", "tiempo": "4 semanas", "horas": 26, "etiquetas": ["Práctica espaciada", "Repaso"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Estudiar todo la noche anterior es común y a veces funciona para aprobar, pero se olvida rápido. Repasar en días distintos suele ayudar a retener más, aunque cuesta organizarlo y pocas personas lo prueban.", "Un sistema de repaso realista convierte esa idea en un hábito sencillo."], "desarrollar": ["Elige dos temas de dificultad parecida: uno lo estudias en una sola sesión larga y el otro en tres sesiones más cortas separadas por uno o dos días. Una semana después responde una prueba de ambos y compara.", "Con los resultados diseña un sistema de repaso para un curso real: qué repasar, cuándo y con qué ejercicios, y pruébalo durante dos semanas con una hoja de seguimiento."], "ampliaciones": [{"titulo": "Intervalos", "aporta": "prueba distintos intervalos entre repasos."}, {"titulo": "Recordatorios", "aporta": "compara agendas, hojas o recordatorios en el celular."}, {"titulo": "Varios cursos", "aporta": "ajusta el sistema para cuatro cursos a la vez."}], "objetivos": ["Comparar estudio concentrado y espaciado.", "Medir el recuerdo.", "Diseñar un sistema de repaso.", "Evaluar su uso."], "habilidades": ["Diseño de experimentos.", "Planificación.", "Autodisciplina.", "Análisis simple de datos."], "herramientas": ["Hoja de cálculo.", "Un calendario.", "Pruebas cortas propias."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Mantén iguales los tiempos totales de estudio de ambas condiciones para comparar con justicia."], "otroSector": "El mismo sistema sirve para repasar vocabulario de un idioma, procedimientos de trabajo o manuales técnicos."}$a3sld$::jsonb,10),
('que-ocurre-cuando-intentamos-estudiar-varias-materias-al-mismo-t','educacion',array[]::text[],'¿Qué ocurre cuando intentamos estudiar varias materias al mismo tiempo?','Compara estudiar un curso por bloques con alternar varios cursos en una misma sesión, y observa qué pasa con tu concentración, tu comprensión y tu recuerdo.','Investigación','3 semanas',22,array['Estudio intercalado','Concentración']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social autoobservacion. registro de datos. comparacion. planificacion. hoja de calculo. un temporizador. pruebas cortas propias.',$a4sld${"id": "que-ocurre-cuando-intentamos-estudiar-varias-materias-al-mismo-t", "area": "educacion", "areas2": [], "titulo": "¿Qué ocurre cuando intentamos estudiar varias materias al mismo tiempo?", "resumen": "Compara estudiar un curso por bloques con alternar varios cursos en una misma sesión, y observa qué pasa con tu concentración, tu comprensión y tu recuerdo.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Estudio intercalado", "Concentración"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["En épocas de exámenes la carga obliga a repartir el tiempo entre varios cursos. Se discute si conviene terminar uno antes de pasar al otro o alternarlos, pero cada estudiante lo decide por intuición.", "Observar el efecto en tu propia rutina permite elegir una forma de repartir el tiempo con criterio."], "desarrollar": ["Durante tres semanas alterna dos formas de estudiar tres cursos: bloques largos de un solo curso por día y sesiones donde alternas los tres cursos cada 40 minutos.", "Anota tu concentración, tus dificultades para retomar y tu desempeño en pruebas cortas de cada curso. Compara ambas formas y describe en qué situaciones conviene cada una."], "ampliaciones": [{"titulo": "Tipos de cursos", "aporta": "analiza si cambia al alternar cursos parecidos o muy distintos."}, {"titulo": "Cambio de tarea", "aporta": "mide cuánto tardas en concentrarte tras cada cambio."}, {"titulo": "Plan semanal", "aporta": "arma un plan que combine ambas formas."}], "objetivos": ["Comparar dos formas de repartir el estudio.", "Registrar concentración y desempeño.", "Identificar situaciones de uso.", "Proponer un plan."], "habilidades": ["Autoobservación.", "Registro de datos.", "Comparación.", "Planificación."], "herramientas": ["Hoja de cálculo.", "Un temporizador.", "Pruebas cortas propias."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Aclara que lo que te sirve a ti puede no servir a otros."], "otroSector": "El mismo análisis sirve para decidir cómo repartir tareas distintas en un trabajo con varios proyectos."}$a4sld$::jsonb,11),
('como-influye-ensenar-un-tema-a-otra-persona-en-nuestra-propia-co','educacion',array['sociedad']::text[],'¿Cómo influye enseñar un tema a otra persona en nuestra propia comprensión?','Mide si explicar un tema a otra persona mejora tu comprensión frente a solo estudiarlo, y descubre qué partes se aclaran al enseñar y cuáles se revelan como dudas.','Investigación','3 semanas',22,array['Aprender enseñando','Comprensión']::text[],array['investigar','resolver']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion explicacion oral. autoevaluacion. diseno de experimentos. comunicacion. una hoja de registro. pruebas cortas propias. un companero dispuesto.',$a5sld${"id": "como-influye-ensenar-un-tema-a-otra-persona-en-nuestra-propia-co", "area": "educacion", "areas2": ["sociedad"], "titulo": "¿Cómo influye enseñar un tema a otra persona en nuestra propia comprensión?", "resumen": "Mide si explicar un tema a otra persona mejora tu comprensión frente a solo estudiarlo, y descubre qué partes se aclaran al enseñar y cuáles se revelan como dudas.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Aprender enseñando", "Comprensión"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Se suele decir que se aprende más al enseñar, pero casi nunca se mide. Explicar obliga a ordenar ideas y a notar vacíos, aunque también puede dar una falsa sensación de dominio si la otra persona solo asiente.", "Probarlo con tus temas ayuda a decidir cuándo vale la pena explicar y a quién."], "desarrollar": ["Elige dos temas de dificultad parecida: uno lo estudias solo y el otro lo estudias y luego lo explicas a un compañero o a un familiar, sin consultar apuntes. Una semana después responde una prueba de ambos.", "Anota qué dudas aparecieron al explicar, qué preguntas te hicieron y cuáles no supiste responder. Compara resultados y resume cómo convertir explicar en un hábito de repaso."], "ampliaciones": [{"titulo": "Explicar a distintos públicos", "aporta": "compara explicar a un experto, a un compañero y a un niño."}, {"titulo": "Explicar por escrito", "aporta": "compara la explicación oral con la escrita."}, {"titulo": "Grabarte", "aporta": "explícate a ti mismo con una grabación y revisa lo dicho."}], "objetivos": ["Medir el efecto de enseñar.", "Detectar vacíos al explicar.", "Comparar con estudiar solo.", "Proponer el hábito."], "habilidades": ["Explicación oral.", "Autoevaluación.", "Diseño de experimentos.", "Comunicación."], "herramientas": ["Una hoja de registro.", "Pruebas cortas propias.", "Un compañero dispuesto."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "El mismo método sirve para capacitar equipos de trabajo en los que unos enseñan a otros."}$a5sld$::jsonb,12),
('que-tan-utiles-son-los-mapas-conceptuales-para-comprender-temas','educacion',array['tecnologia']::text[],'¿Qué tan útiles son los mapas conceptuales para comprender temas complejos?','Prueba si construir un mapa conceptual de un tema complejo mejora tu comprensión frente a solo leerlo o resumirlo, y descubre en qué tipos de temas ayuda más.','Investigación','2 a 3 semanas',20,array['Mapas conceptuales','Comprensión']::text[],array['investigar','crear']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion construccion de mapas. sintesis de ideas. evaluacion de comprension. diseno de guias. un editor de mapas conceptuales o papel. hoja de calculo. preguntas de aplicacion.',$a6sld${"id": "que-tan-utiles-son-los-mapas-conceptuales-para-comprender-temas", "area": "educacion", "areas2": ["tecnologia"], "titulo": "¿Qué tan útiles son los mapas conceptuales para comprender temas complejos?", "resumen": "Prueba si construir un mapa conceptual de un tema complejo mejora tu comprensión frente a solo leerlo o resumirlo, y descubre en qué tipos de temas ayuda más.", "tipo": "Investigación", "tiempo": "2 a 3 semanas", "horas": 20, "etiquetas": ["Mapas conceptuales", "Comprensión"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Los mapas conceptuales se enseñan mucho, pero se usan poco y a veces se vuelven un dibujo bonito que no ayuda a entender. No se sabe en qué temas aportan realmente.", "Compararlos con otras formas de estudiar ayuda a decidir cuándo usarlos y cómo hacerlos bien."], "desarrollar": ["Elige un tema con muchos conceptos relacionados y estudia tres partes con métodos distintos: leer, resumir y construir un mapa conceptual. Luego responde preguntas que exijan relacionar ideas, no solo recordar datos.", "Compara los resultados, revisa tus mapas para ver qué los hizo útiles y arma una guía breve de buenas prácticas para construir mapas conceptuales."], "ampliaciones": [{"titulo": "Papel o digital", "aporta": "compara mapas a mano con mapas en una herramienta digital."}, {"titulo": "Mapa de un curso", "aporta": "construye un mapa de todo un curso para repasar antes del examen."}, {"titulo": "Mapa colaborativo", "aporta": "construye mapas en grupo y compara con los individuales."}], "objetivos": ["Comparar mapas con otras técnicas.", "Medir la comprensión.", "Identificar buenas prácticas.", "Elaborar una guía."], "habilidades": ["Construcción de mapas.", "Síntesis de ideas.", "Evaluación de comprensión.", "Diseño de guías."], "herramientas": ["Un editor de mapas conceptuales o papel.", "Hoja de cálculo.", "Preguntas de aplicación."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Evalúa comprensión con preguntas que pidan relacionar y explicar, no solo repetir."], "otroSector": "El mismo método sirve para organizar la información de un proyecto, un informe o una investigación."}$a6sld$::jsonb,13),
('comparando-el-aprendizaje-con-videos-lecturas-y-ejercicios-pract','educacion',array['tecnologia']::text[],'Comparando el aprendizaje con videos, lecturas y ejercicios prácticos: ¿leer o resolver ejercicios?','Aprende un mismo tipo de tema con un video, con una lectura o resolviendo ejercicios, y compara cuánto aprendes, cuánto tardas y qué combinación funciona mejor para ti.','Investigación','3 a 4 semanas',24,array['Formatos de aprendizaje','Práctica']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social diseno de experimentos. registro de tiempo. comparacion. analisis simple de datos. hoja de calculo. videos y lecturas de calidad. pruebas cortas propias.',$a7sld${"id": "comparando-el-aprendizaje-con-videos-lecturas-y-ejercicios-pract", "area": "educacion", "areas2": ["tecnologia"], "titulo": "Comparando el aprendizaje con videos, lecturas y ejercicios prácticos: ¿leer o resolver ejercicios?", "resumen": "Aprende un mismo tipo de tema con un video, con una lectura o resolviendo ejercicios, y compara cuánto aprendes, cuánto tardas y qué combinación funciona mejor para ti.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Formatos de aprendizaje", "Práctica"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Cada formato tiene sus fans: los videos parecen más cómodos, las lecturas más profundas y los ejercicios más difíciles. Sin embargo, casi nunca se mide qué te deja realmente más aprendizaje por hora de estudio.", "Saber cómo rindes con cada formato permite armar una combinación eficiente."], "desarrollar": ["Elige tres temas de dificultad parecida y estudia cada uno con un formato distinto: un video, una lectura y una serie de ejercicios con soluciones. Mide el tiempo que invertiste en cada uno.", "Responde una prueba corta de cada tema, compara puntajes por hora invertida y observa qué combinaciones, por ejemplo video más ejercicios, funcionan mejor. Resume tu conclusión en un cuadro."], "ampliaciones": [{"titulo": "Tipos de contenido", "aporta": "compara si el resultado cambia en temas teóricos y en temas de cálculo."}, {"titulo": "Combinaciones", "aporta": "prueba combinar dos formatos para el mismo tema."}, {"titulo": "Con compañeros", "aporta": "repite con otras personas y compara."}], "objetivos": ["Comparar tres formatos.", "Medir el aprendizaje por hora.", "Identificar combinaciones eficaces.", "Resumir conclusiones."], "habilidades": ["Diseño de experimentos.", "Registro de tiempo.", "Comparación.", "Análisis simple de datos."], "herramientas": ["Hoja de cálculo.", "Videos y lecturas de calidad.", "Pruebas cortas propias."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Usa materiales equivalentes en contenido para que la comparación sea justa."], "otroSector": "El mismo análisis sirve para elegir formatos de capacitación interna en una empresa."}$a7sld$::jsonb,14),
('que-tipo-de-preguntas-ayuda-mas-a-comprender-un-tema-recordar-ex','educacion',array[]::text[],'¿Qué tipo de preguntas ayuda más a comprender un tema: recordar, explicar o aplicar?','Compara estudiar con preguntas de recordar datos, de explicar con tus palabras o de aplicar a un caso nuevo, y descubre cuáles te preparan mejor para entender y resolver problemas.','Investigación','2 a 3 semanas',20,array['Autopreguntas','Comprensión']::text[],array['investigar','crear']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion formulacion de preguntas. analisis de resultados. pensamiento critico. diseno de materiales. hoja de calculo. un editor de documentos. material de estudio.',$a8sld${"id": "que-tipo-de-preguntas-ayuda-mas-a-comprender-un-tema-recordar-ex", "area": "educacion", "areas2": [], "titulo": "¿Qué tipo de preguntas ayuda más a comprender un tema: recordar, explicar o aplicar?", "resumen": "Compara estudiar con preguntas de recordar datos, de explicar con tus palabras o de aplicar a un caso nuevo, y descubre cuáles te preparan mejor para entender y resolver problemas.", "tipo": "Investigación", "tiempo": "2 a 3 semanas", "horas": 20, "etiquetas": ["Autopreguntas", "Comprensión"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Al estudiar muchos se limitan a preguntas de recordar, como definiciones o fechas, y luego se sorprenden cuando el examen pide explicar o aplicar. No todas las preguntas exigen el mismo esfuerzo mental ni dejan el mismo aprendizaje.", "Escoger bien qué preguntas hacerse puede cambiar la calidad del estudio."], "desarrollar": ["Elige un tema y escribe tres bancos de preguntas: de recordar, de explicar y de aplicar. Estudia tres partes del tema con cada banco y luego responde una prueba mixta.", "Analiza en qué tipo de pregunta rendiste mejor según cómo estudiaste y redacta una guía con ejemplos de cada tipo para que otros estudiantes se formulen mejores preguntas."], "ampliaciones": [{"titulo": "Banco de preguntas", "aporta": "arma un banco de preguntas por nivel para un curso."}, {"titulo": "Preguntas de compañeros", "aporta": "intercambia preguntas con compañeros y resuélvelas."}, {"titulo": "Preguntas de examen", "aporta": "clasifica preguntas de exámenes anteriores por tipo."}], "objetivos": ["Distinguir tipos de preguntas.", "Comparar su efecto.", "Elaborar bancos de preguntas.", "Redactar una guía."], "habilidades": ["Formulación de preguntas.", "Análisis de resultados.", "Pensamiento crítico.", "Diseño de materiales."], "herramientas": ["Hoja de cálculo.", "Un editor de documentos.", "Material de estudio."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Basa tus ejemplos en temas que domines para que las preguntas sean correctas."], "otroSector": "El mismo enfoque sirve para diseñar evaluaciones de capacitación o entrevistas técnicas."}$a8sld$::jsonb,15),
('sistema-de-tarjetas-de-estudio-que-tan-efectivas-son-para-aprend','educacion',array['tecnologia']::text[],'Sistema de tarjetas de estudio: ¿qué tan efectivas son para aprender conceptos de una materia?','Diseña un sistema de tarjetas para los conceptos de un curso, pruébalo frente a otras formas de repaso y mide si realmente ayuda a recordar y a comprender.','Investigación','3 a 4 semanas',24,array['Tarjetas de estudio','Memoria']::text[],array['investigar','crear']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social diseno de materiales. sintesis. experimentacion. organizacion del repaso. tarjetas de papel o una hoja de calculo. pruebas cortas propias. un temporizador.',$a9sld${"id": "sistema-de-tarjetas-de-estudio-que-tan-efectivas-son-para-aprend", "area": "educacion", "areas2": ["tecnologia"], "titulo": "Sistema de tarjetas de estudio: ¿qué tan efectivas son para aprender conceptos de una materia?", "resumen": "Diseña un sistema de tarjetas para los conceptos de un curso, pruébalo frente a otras formas de repaso y mide si realmente ayuda a recordar y a comprender.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Tarjetas de estudio", "Memoria"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Las tarjetas de estudio son populares, pero muchas se arman mal: con demasiado texto, sin orden de repaso o solo para memorizar definiciones. Rara vez se mide si sirven más que releer los apuntes.", "Un sistema bien diseñado y comparado con otras formas de repasar dice si vale la pena el esfuerzo."], "desarrollar": ["Elige un curso y crea un conjunto de tarjetas con criterios claros: una idea por tarjeta, preguntas en vez de definiciones copiadas y una regla de cuándo repasar cada una, ya sea en papel o en una hoja de cálculo.", "Estudia dos partes del curso, una con tarjetas y otra con relectura, y compara el recuerdo y la comprensión en una prueba corta. Ajusta el diseño de las tarjetas según los resultados."], "ampliaciones": [{"titulo": "Papel o digital", "aporta": "compara tarjetas físicas con tarjetas en una herramienta digital ya existente."}, {"titulo": "Tarjetas de aplicación", "aporta": "agrega tarjetas con casos y no solo con datos."}, {"titulo": "Tarjetas compartidas", "aporta": "intercambia tarjetas con compañeros y evalúa su utilidad."}], "objetivos": ["Diseñar tarjetas con criterios claros.", "Compararlas con otras formas de repaso.", "Medir su efecto.", "Mejorar el sistema."], "habilidades": ["Diseño de materiales.", "Síntesis.", "Experimentación.", "Organización del repaso."], "herramientas": ["Tarjetas de papel o una hoja de cálculo.", "Pruebas cortas propias.", "Un temporizador."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Usa solo herramientas ya existentes si pruebas versión digital."], "otroSector": "El mismo sistema sirve para aprender vocabulario de un idioma o procedimientos de un trabajo."}$a9sld$::jsonb,16),
('cuanto-tiempo-necesitamos-para-recuperar-la-concentracion-despue','educacion',array['tecnologia','salud']::text[],'¿Cuánto tiempo necesitamos para recuperar la concentración después de una interrupción?','Mide cuánto tardas en volver a concentrarte tras interrupciones como un mensaje o una conversación, y cómo cambia tu rendimiento en tareas con y sin interrupciones.','Investigación','2 a 3 semanas',20,array['Concentración','Interrupciones']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social autoobservacion. registro de datos. calculo simple. planificacion. hoja de calculo. un cronometro. un cuaderno de registro.',$a10sld${"id": "cuanto-tiempo-necesitamos-para-recuperar-la-concentracion-despue", "area": "educacion", "areas2": ["tecnologia", "salud"], "titulo": "¿Cuánto tiempo necesitamos para recuperar la concentración después de una interrupción?", "resumen": "Mide cuánto tardas en volver a concentrarte tras interrupciones como un mensaje o una conversación, y cómo cambia tu rendimiento en tareas con y sin interrupciones.", "tipo": "Investigación", "tiempo": "2 a 3 semanas", "horas": 20, "etiquetas": ["Concentración", "Interrupciones"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Un mensaje en el celular parece algo mínimo, pero retomar el hilo de un ejercicio o una lectura puede tomar varios minutos. Sumadas, las interrupciones pueden quitar buena parte de una sesión sin que lo notemos.", "Medirlo en tu propia rutina hace visible el costo y ayuda a decidir qué interrupciones evitar."], "desarrollar": ["Durante dos semanas registra cada interrupción durante el estudio: tipo, duración y cuánto tardas en retomar la tarea con el mismo ritmo, usando una tarea simple como medidor, por ejemplo cuántos ejercicios resuelves por intervalo.", "Compara sesiones con y sin interrupciones, calcula el tiempo perdido al día y propón tres cambios concretos, como silenciar notificaciones o agrupar los mensajes en ciertos horarios."], "ampliaciones": [{"titulo": "Tipo de interrupción", "aporta": "compara mensajes, personas y ruidos."}, {"titulo": "Prueba del modo silencio", "aporta": "mide una semana con notificaciones apagadas."}, {"titulo": "Costo semanal", "aporta": "estima las horas perdidas en una semana."}], "objetivos": ["Medir el costo de interrumpirse.", "Clasificar interrupciones.", "Calcular el tiempo perdido.", "Proponer cambios."], "habilidades": ["Autoobservación.", "Registro de datos.", "Cálculo simple.", "Planificación."], "herramientas": ["Hoja de cálculo.", "Un cronómetro.", "Un cuaderno de registro."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "No te pongas metas de cero interrupciones: busca reducir las que más te cuestan."], "otroSector": "El mismo registro sirve para medir interrupciones en una oficina, en clases o en trabajo remoto."}$a10sld$::jsonb,17),
('como-influye-el-orden-de-los-temas-en-la-dificultad-de-aprender','educacion',array['tecnologia']::text[],'¿Cómo influye el orden de los temas en la dificultad de aprender una materia?','Analiza cómo cambia la dificultad de un curso según el orden en que se presentan los temas y propone una secuencia más clara usando dependencias entre conceptos.','Análisis','3 semanas',22,array['Secuencia','Dificultad']::text[],array['investigar','crear']::text[],'ficticios',NULL,'educacion ingenieria de sistemas ciencia de datos psicologia comunicaciones estadistica diseno administracion analisis de dependencias. diagramacion. pensamiento didactico. comunicacion. un editor de diagramas. el silabo del curso. hoja de calculo.',$a11sld${"id": "como-influye-el-orden-de-los-temas-en-la-dificultad-de-aprender", "area": "educacion", "areas2": ["tecnologia"], "titulo": "¿Cómo influye el orden de los temas en la dificultad de aprender una materia?", "resumen": "Analiza cómo cambia la dificultad de un curso según el orden en que se presentan los temas y propone una secuencia más clara usando dependencias entre conceptos.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Secuencia", "Dificultad"], "intencion": ["investigar", "crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Comunicaciones", "Estadística", "Diseño", "Administración"], "problema": ["Muchos cursos presentan los temas en el orden del libro o del sílabo, aunque algunos requieren conceptos que aparecen más tarde. Eso genera la sensación de entender poco sin saber qué falta.", "Mapear qué concepto depende de cuál permite proponer un orden de estudio mejor."], "desarrollar": ["Elige un curso que domines y lista sus temas con los conceptos previos que cada uno exige. Dibuja un mapa de dependencias y detecta los temas puente, que si fallan arrastran a los siguientes.", "Compara el orden del sílabo con el orden que sugiere tu mapa, propón una secuencia alternativa y pídele a dos compañeros que la comenten."], "ampliaciones": [{"titulo": "Pruebas de entrada", "aporta": "propón preguntas cortas para detectar qué falta antes de cada tema."}, {"titulo": "Dos cursos", "aporta": "compara las dependencias de dos cursos relacionados."}, {"titulo": "Guía de estudio", "aporta": "convierte el mapa en una ruta de estudio para el ciclo."}], "objetivos": ["Mapear dependencias entre temas.", "Detectar temas puente.", "Proponer una secuencia alternativa.", "Validarla con otros."], "habilidades": ["Análisis de dependencias.", "Diagramación.", "Pensamiento didáctico.", "Comunicación."], "herramientas": ["Un editor de diagramas.", "El sílabo del curso.", "Hoja de cálculo."], "lineamientos": ["Usa un curso del que conozcas bien el contenido y evita criticar a docentes concretos: analiza el diseño de la secuencia.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir."], "otroSector": "El mismo mapa sirve para ordenar la capacitación de un equipo nuevo o el aprendizaje de un lenguaje de programación."}$a11sld$::jsonb,18),
('comparando-metodos-de-toma-de-apuntes-en-una-misma-asignatura','educacion',array[]::text[],'Comparando métodos de toma de apuntes en una misma asignatura','Prueba distintos métodos de tomar apuntes, como el de Cornell, mapas, resúmenes o transcripción, en un mismo curso y mide con cuál repasas y comprendes mejor.','Investigación','3 a 4 semanas',22,array['Apuntes','Métodos']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social sintesis. experimentacion. autoevaluacion. organizacion de informacion. cuaderno o editor de notas. hoja de calculo. preguntas de prueba propias.',$a12sld${"id": "comparando-metodos-de-toma-de-apuntes-en-una-misma-asignatura", "area": "educacion", "areas2": [], "titulo": "Comparando métodos de toma de apuntes en una misma asignatura", "resumen": "Prueba distintos métodos de tomar apuntes, como el de Cornell, mapas, resúmenes o transcripción, en un mismo curso y mide con cuál repasas y comprendes mejor.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Apuntes", "Métodos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Se toman apuntes de formas muy distintas, desde copiar todo lo que dice el docente hasta dibujar esquemas. Pero pocas veces se compara qué método deja materiales más útiles para estudiar después.", "Probar varios métodos en un mismo curso permite elegir con evidencia."], "desarrollar": ["Durante tres a cuatro clases del mismo curso toma apuntes con métodos distintos en cada una, por ejemplo Cornell, esquema, resumen en tus palabras y transcripción casi literal.", "Una semana después, estudia cada conjunto de apuntes por separado y responde preguntas sobre cada clase. Compara resultados, tiempo de repaso y comodidad, y elige tu método o una combinación."], "ampliaciones": [{"titulo": "A mano o en pantalla", "aporta": "compara apuntes escritos con apuntes digitales."}, {"titulo": "Apuntes mejorados", "aporta": "agrega una pasada de resumen posterior a cada clase."}, {"titulo": "Intercambio", "aporta": "estudia con los apuntes de un compañero y compara."}], "objetivos": ["Probar distintos métodos de apuntes.", "Medir su utilidad al repasar.", "Elegir un método.", "Documentar la comparación."], "habilidades": ["Síntesis.", "Experimentación.", "Autoevaluación.", "Organización de información."], "herramientas": ["Cuaderno o editor de notas.", "Hoja de cálculo.", "Preguntas de prueba propias."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Si usas apuntes de un compañero, pide su permiso y no los compartas."], "otroSector": "El mismo análisis sirve para comparar formas de registrar reuniones o entrevistas."}$a12sld$::jsonb,19),
('comparando-el-aprendizaje-individual-y-el-aprendizaje-en-grupo','educacion',array['sociedad']::text[],'Comparando el aprendizaje individual y el aprendizaje en grupo','Compara estudiar solo y estudiar en grupo un mismo tipo de tema, y analiza en qué situaciones cada forma rinde más y qué hace que un grupo de estudio funcione o se vuelva una conversación social.','Investigación','3 semanas',22,array['Estudio en grupo','Colaboración']::text[],array['investigar','resolver']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion trabajo en equipo. observacion. comparacion. redaccion de guias. hoja de calculo. un temporizador. pruebas cortas propias.',$a13sld${"id": "comparando-el-aprendizaje-individual-y-el-aprendizaje-en-grupo", "area": "educacion", "areas2": ["sociedad"], "titulo": "Comparando el aprendizaje individual y el aprendizaje en grupo", "resumen": "Compara estudiar solo y estudiar en grupo un mismo tipo de tema, y analiza en qué situaciones cada forma rinde más y qué hace que un grupo de estudio funcione o se vuelva una conversación social.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Estudio en grupo", "Colaboración"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Los grupos de estudio pueden ser muy productivos o una pérdida de tiempo, según cómo se organicen. Unos aprenden más al discutir y otros se distraen y terminan dependiendo de quien más sabe.", "Entender cuándo conviene estudiar solo y cuándo en grupo mejora la planificación del ciclo."], "desarrollar": ["Con tres o cuatro compañeros, estudien un tema en grupo con una estructura definida y otro tema de dificultad parecida cada uno por su lado. Luego respondan una prueba corta de ambos y comparen resultados.", "Registren cuánto tiempo se dedicó realmente al tema en el grupo, cómo se repartieron los roles y qué tipo de actividades funcionaron, y redacten una guía para organizar un grupo de estudio."], "ampliaciones": [{"titulo": "Roles", "aporta": "prueba asignar roles, como explicador, preguntador y verificador."}, {"titulo": "Tamaño del grupo", "aporta": "compara grupos de dos, tres y cinco personas."}, {"titulo": "Virtual o presencial", "aporta": "compara estudiar en persona con hacerlo por videollamada."}], "objetivos": ["Comparar estudio individual y grupal.", "Analizar la dinámica del grupo.", "Proponer una guía.", "Validarla."], "habilidades": ["Trabajo en equipo.", "Observación.", "Comparación.", "Redacción de guías."], "herramientas": ["Hoja de cálculo.", "Un temporizador.", "Pruebas cortas propias."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Los resultados son de un grupo pequeño: preséntalos como casos de estudio, no como regla general."], "otroSector": "El mismo análisis sirve para equipos de proyecto o grupos de estudio de oposiciones."}$a13sld$::jsonb,20)
